    .{ .sym = "op_fld_path", .id = "field.copy_path", .label = "Copy Data Path", .doc = "Its path for scripts and anim.key (Cube:x, material:Steel:roughness) to the clipboard", .hidden = true },
    .{ .sym = "op_add_bezier", .id = "create.bezier", .label = "Bezier Curve", .doc = "Add a Bezier curve (Tab edits its points)" },
    .{ .sym = "op_add_ccircle", .id = "create.curve_circle", .label = "Bezier Circle", .doc = "Add a closed Bezier circle" },
    .{ .sym = "op_add_path", .id = "create.path", .label = "Path", .doc = "Add a poly path of five points" },
    .{ .sym = "op_cv_add", .id = "curve.add", .label = "Curve", .doc = "Add a curve at the 3D cursor: curve.add [bezier|circle|path|empty]" },
    .{ .sym = "op_cv_set", .id = "curve.set", .label = "Set Curve Value", .doc = "A value of the active curve: curve.set <resolution|bevel|sides|fill|profile|cyclic> <value> (profile: a curve's name, or none)" },
    .{ .sym = "op_cv_point", .id = "curve.point", .label = "Add Curve Point", .doc = "A control point at the end of the active curve's spline: curve.point <x> <y> <z> (object space)" },
    .{ .sym = "op_cv_spline", .id = "curve.spline", .label = "New Spline", .doc = "Start a spline in the active curve (later points go to it): curve.spline <bezier|poly> [cyclic]" },
    .{ .sym = "op_cv_tomesh", .id = "curve.to_mesh", .label = "Convert Curve to Mesh", .doc = "The active curve becomes the plain mesh it makes" },
    .{ .sym = "op_cv_select", .id = "curve.select", .label = "Select Curve Points", .doc = "Select control points of the active curve: curve.select <i> [i ...] | all | none" },
    .{ .sym = "op_cv_move", .id = "curve.move", .label = "Move Curve Point", .doc = "Place a control point (its handles follow) or one handle: curve.move <i> <x> <y> <z> [left|right] (object space)" },
    .{ .sym = "op_cv_selall", .id = "curve.select_all", .label = "Select All Points", .doc = "Curve edit mode: select every point, or none when some are", .code = 30 },
    .{ .sym = "op_cv_extrude", .id = "curve.extrude", .label = "Extrude Curve", .doc = "New points after the selected end points, then move them: curve.extrude [dx dy dz]", .code = 18 },
    .{ .sym = "op_cv_subdiv", .id = "curve.subdivide", .label = "Subdivide Curve", .doc = "A point between each pair of selected neighbours (the shape kept)", .code = 17 },
    .{ .sym = "op_cv_delete", .id = "curve.delete", .label = "Delete Curve Points", .doc = "Remove the selected control points", .code = 45 },
    .{ .sym = "op_cv_delete2", .id = "curve.delete_key", .label = "Delete Curve Points", .doc = "Remove the selected control points", .code = 111, .hidden = true },
    .{ .sym = "op_cv_cyclic", .id = "curve.cyclic", .label = "Toggle Cyclic", .doc = "Close (or open) the splines holding selected points", .code = 46, .mods = 8 },
    .{ .sym = "op_cv_handle", .id = "curve.handle", .label = "Handle Type", .doc = "Handle type of the selected points: curve.handle [auto|aligned|vector|free] (none: the next type)", .code = 47 },
    .{ .sym = "op_cv_tilt", .id = "curve.tilt", .label = "Curve Tilt", .doc = "Tilt the selected points of the active curve: curve.tilt <degrees>" },
    .{ .sym = "op_cv_radius", .id = "curve.radius", .label = "Curve Radius", .doc = "Radius (sweep scale) of the selected points of the active curve: curve.radius <r>" },
    .{ .sym = "op_dlg_ok", .id = "dialog.ok", .label = "OK", .doc = "Confirm the open dialog", .hidden = true },
    .{ .sym = "op_dlg_alt", .id = "dialog.dont_save", .label = "Don't Save", .doc = "Go on without saving", .hidden = true },
    .{ .sym = "op_dlg_cancel", .id = "dialog.cancel", .label = "Cancel", .doc = "Close the open dialog", .hidden = true },
    .{ .sym = "op_area_float", .id = "area.float", .label = "Float Area", .doc = "Take the active area out of the layout: it floats over the window as a panel you can move and resize (its header's dock button puts it back)" },
    .{ .sym = "op_area_dock", .id = "area.dock", .label = "Dock Area", .doc = "Put the active floating panel back into the layout, beside the area under it" },
    .{ .sym = "op_area_window", .id = "area.new_window", .label = "Open in New Window", .doc = "Put the active area in a window of its own, which you can move to another monitor; closing that window puts the area back" },
    .{ .sym = "op_export_pdf", .id = "file.export_pdf", .label = "Export Drawing (PDF)...", .doc = "A drawing of the selected meshes (or all): front, top and right views with hidden lines dashed, overall dimensions and a title block, on A4 as PDF: file.export_pdf <path>" },
    .{ .sym = "op_dr_opts", .id = "drawing.options", .label = "Drawing Options", .doc = "How Export Drawing lays out the page: drawing.options [a4|a3|a2|letter] [landscape|portrait] [views front top right iso] [scale auto|2:1|1:1|1:2|1:5|1:10|1:20|1:50|1:100] [title \"...\"] [author \"...\"]" },
    .{ .sym = "op_s_dyn", .id = "sculpt.dyntopo", .label = "Dynamic Topology", .doc = "Sculpt: brushes add and remove triangles to keep the detail size (the mesh becomes triangles)", .code = 32, .mods = 4 },
    .{ .sym = "op_s_dfine", .id = "sculpt.detail_finer", .label = "Finer Detail", .doc = "Sculpt: dyntopo detail size x 0.8 (pixels)", .code = 26, .mods = 4 },
    .{ .sym = "op_s_dcoarse", .id = "sculpt.detail_coarser", .label = "Coarser Detail", .doc = "Sculpt: dyntopo detail size x 1.25 (pixels)", .code = 27, .mods = 4 },
    .{ .sym = "op_edit_toggle", .id = "mode.toggle_edit", .label = "Edit Mode", .doc = "Switch the active mesh between object mode and edit mode", .code = 15 },
    .{ .sym = "op_selmode_v", .id = "mesh.select_mode_vertex", .label = "Vertex Select Mode", .doc = "Edit mode: pick vertices", .code = 2 },
    .{ .sym = "op_selmode_e", .id = "mesh.select_mode_edge", .label = "Edge Select Mode", .doc = "Edit mode: pick edges", .code = 3 },
    .{ .sym = "op_selmode_f", .id = "mesh.select_mode_face", .label = "Face Select Mode", .doc = "Edit mode: pick faces", .code = 4 },
    .{ .sym = "op_mesh_all", .id = "mesh.select_all", .label = "Select All / None (Mesh)", .doc = "Edit mode: select every vertex, or none if some are selected", .code = 30 },
    .{ .sym = "op_mesh_inv", .id = "mesh.select_invert", .label = "Invert Selection", .doc = "Edit mode: invert the vertex selection", .code = 23, .mods = 4 },
    .{ .sym = "op_mesh_linked", .id = "mesh.select_linked", .label = "Select Linked", .doc = "Edit mode: grow the selection over every connected part", .code = 38, .mods = 4 },
    .{ .sym = "op_mesh_box", .id = "mesh.select_box", .label = "Box Select", .doc = "Edit mode: drag a rectangle to select (Ctrl subtracts)", .code = 48 },
    .{ .sym = "op_world_hdri", .id = "world.hdri", .label = "World HDRI", .doc = "Light the scene with an equirectangular image: world.hdri <image|none>" },
    .{ .sym = "op_world_strength", .id = "world.strength", .label = "World Strength", .doc = "Scale the world's light: world.strength <factor>" },
    .{ .sym = "op_world_rotation", .id = "world.rotation", .label = "World Rotation", .doc = "Turn the world image about the vertical: world.rotation <degrees>" },
    .{ .sym = "op_ex_sources", .id = "lib.sources", .label = "Library Sources", .doc = "List the asset libraries: the local one and the online sources (lib.source <id> shows one in the Asset Browser)" },
    .{ .sym = "op_ex_source", .id = "lib.source", .label = "Library Source", .doc = "Show an asset library in the Asset Browser: lib.source <id> (an online source: its catalog is fetched the first time) | local" },
    .{ .sym = "op_ex_snext", .id = "lib.source_next", .label = "Next Library Source", .doc = "Show the next asset library in the Asset Browser (the local library, then each online source)" },
    .{ .sym = "op_ex_refresh", .id = "lib.refresh", .label = "Refresh Catalog", .doc = "Fetch the online source's catalog again (new assets)" },
    .{ .sym = "op_ex_get", .id = "lib.get", .label = "Get Online Asset", .doc = "Place an asset of the online source shown (lib.source <id>): its files are downloaded the first time, then it is imported at the 3D cursor (or x y z) with its materials and physics, and saved into the local library: lib.get <asset name> [x y z] [static] [nosave] (static: no rigid bodies or joints; nosave: not into the library)" },
    .{ .sym = "op_ex_stop", .id = "lib.stop", .label = "Stop Downloads", .doc = "Stop the online library's downloads (files fetched so far are kept)" },
    .{ .sym = "op_export_3mf", .id = "file.export_3mf", .label = "Export 3MF...", .doc = "Export the mesh objects for 3D printing as 3MF (millimetres, Z up): file.export_3mf <path>" },
    .{ .sym = "op_export_dxf", .id = "file.export_dxf", .label = "Export DXF...", .doc = "Export the active sketch (or the first) as DXF in millimetres: file.export_dxf <path>" },
    .{ .sym = "op_export_svg", .id = "file.export_svg", .label = "Export SVG...", .doc = "Export the active sketch (or the first) as SVG in millimetres: file.export_svg <path>" },
    .{ .sym = "op_fl_attr", .id = "field.add_attractor", .label = "Attractor", .doc = "Add an Attractor at the 3D cursor: it pulls rigid bodies, cloth and particles towards it (strength / distance squared; a negative strength pushes away): field.add_attractor [strength s] [law square|linear] [soft m] [falloff none|radius|smooth] [radius m] [groups all|0,3]" },
    .{ .sym = "op_fl_zone", .id = "field.add_zone", .label = "Gravity Zone", .doc = "Add a Gravity Zone: inside its box (or sphere) down is the object's -Y at this strength instead of the world's gravity: field.add_zone [strength s] [shape box|sphere] [size half-size m]" },
    .{ .sym = "op_fl_wind", .id = "field.add_wind", .label = "Wind", .doc = "Add Wind: it blows along the object's +X (rotate it to aim), with gusts; cloth feels it as air of this speed (m/s): field.add_wind [strength s] [gust 0..1] [falloff none|radius|smooth] [radius m]" },
    .{ .sym = "op_fl_vortex", .id = "field.add_vortex", .label = "Vortex", .doc = "Add a Vortex: it turns things round the object's +Y: field.add_vortex [strength s] [lift s] [inflow s] [falloff none|radius|smooth] [radius m]" },
    .{ .sym = "op_fl_turb", .id = "field.add_turbulence", .label = "Turbulence", .doc = "Add Turbulence: swirling curl noise: field.add_turbulence [strength s] [scale m] [seed n] [falloff none|radius|smooth] [radius m]" },
    .{ .sym = "op_fl_drag", .id = "field.add_drag", .label = "Drag", .doc = "Add Drag: it slows things down (strength x their velocity): field.add_drag [strength s] [falloff none|radius|smooth] [radius m]" },
    .{ .sym = "op_fl_planet", .id = "field.add_planet", .label = "Planet", .doc = "Add a planet at the 3D cursor: a 10 m sphere with an Attractor at its centre (9.81 m/s2 at its surface) and the world's gravity off - walk round it in play mode" },
    .{ .sym = "op_fl_hole", .id = "field.add_blackhole", .label = "Black Hole", .doc = "Add a Black Hole: a strong, short Attractor (strength 2000, smooth falloff to 8 m)" },
    .{ .sym = "op_fl_tornado", .id = "field.add_tornado", .label = "Tornado", .doc = "Add a Tornado: a Vortex that turns things round its +Y, lifts them and pulls them in (smooth falloff to 6 m)" },
    .{ .sym = "op_fl_breeze", .id = "field.add_breeze", .label = "Breeze", .doc = "Add a Breeze: gentle, gusty Wind along +X" },
    .{ .sym = "op_fl_arrows", .id = "view.field_arrows", .label = "Force Field Arrows", .doc = "Show the force fields' pull as arrows on a grid round them (gravity left out)" },
    .{ .sym = "op_fl_lines", .id = "view.field_lines", .label = "Force Field Lines", .doc = "Show the force fields' pull as lines (streamlines) from the selected objects" },
    .{ .sym = "op_fl_set", .id = "field.set", .label = "Field Settings", .doc = "The active force field's settings: field.set [type attractor|zone|wind|vortex|turbulence|drag] [strength s] [falloff none|radius|smooth] [radius m] [law square|linear] [shape box|sphere] [gust 0..1] [scale m] [seed n] [lift s] [inflow s] [soft m] [groups all|0,3] [on|off]" },
    .{ .sym = "op_fb_ok", .id = "files.ok", .label = "Open / Save", .doc = "Take the file named in the file browser", .hidden = true },
    .{ .sym = "op_fb_up", .id = "files.up", .label = "Folder Up", .doc = "The file browser: the folder above", .hidden = true },
    .{ .sym = "op_fb_open_row", .id = "files.open_row", .label = "Open", .doc = "Open the folder, or take the file", .hidden = true },
    .{ .sym = "op_fb_rename", .id = "files.rename", .label = "Rename...", .doc = "Give the file or folder a new name (type it in the Name field)", .hidden = true },
    .{ .sym = "op_fb_delete", .id = "files.delete", .label = "Delete...", .doc = "Delete the file, or an empty folder (asks first)", .hidden = true },
    .{ .sym = "op_fb_mkdir", .id = "files.new_folder", .label = "New Folder", .doc = "A new folder here, then type its name", .hidden = true },
    .{ .sym = "op_fb_cpath", .id = "files.copy_path", .label = "Copy Path", .doc = "The file's full path to the clipboard", .hidden = true },
    .{ .sym = "op_fb_back", .id = "files.back", .label = "Back", .doc = "The file browser: the folder shown before (Alt+Left)", .hidden = true },
    .{ .sym = "op_fb_fwd", .id = "files.forward", .label = "Forward", .doc = "The file browser: forward again (Alt+Right)", .hidden = true },
    .{ .sym = "op_fb_fav", .id = "files.favorite", .label = "Favorite", .doc = "The folder shown in the favourites, or out of them", .hidden = true },
    .{ .sym = "op_fb_hidden", .id = "files.show_hidden", .label = "Show Hidden", .doc = "The file browser: files and folders whose names start with a dot (Ctrl+H)", .hidden = true },
    .{ .sym = "op_fd_new", .id = "outliner.folder_new", .label = "New Folder", .doc = "A new folder (inside the folder picked), the selected objects moved into it: outliner.folder_new [name]", .code = 34, .mods = 4 },
    .{ .sym = "op_fd_move", .id = "object.move_to_folder", .label = "Move to Folder...", .doc = "The selected objects into a folder (made when there is none of that name), or out of theirs: object.move_to_folder <name | none>" },
    .{ .sym = "op_fd_ren", .id = "outliner.folder_rename", .label = "Rename Folder", .doc = "The folder picked gets a new name: outliner.folder_rename <name>", .hidden = true },
    .{ .sym = "op_fd_del", .id = "outliner.folder_delete", .label = "Delete Folder", .doc = "The folder picked goes; what was in it moves up a level (contents: its objects are deleted too): outliner.folder_delete [contents]" },
    .{ .sym = "op_fd_col", .id = "outliner.folder_color", .label = "Folder Colour", .doc = "Colour a folder in the outliner (the one picked, or the one named): outliner.folder_color <none|red|orange|yellow|green|teal|blue|purple|pink|next> [folder name]. A click on a folder's icon goes to the next colour" },
    .{ .sym = "op_fd_tidy", .id = "outliner.tidy", .label = "Tidy Outliner", .doc = "Group the objects that are in no folder: lights, cameras, reference images, and objects named alike (Chair, Chair.001, Chair_2 ...) each into a coloured folder of their own (two or more of a kind, children staying with their parents), then folders left empty go" },
    .{ .sym = "op_fd_tidy_ai", .id = "outliner.tidy_ai", .label = "Tidy Outliner with AI", .doc = "Ask the AI Assistant to sort the scene's objects into named, coloured folders by what they are (one undo step)" },
    .{ .sym = "op_fd_sel", .id = "outliner.folder_select", .label = "Select Folder's Objects", .doc = "Select every object in the folder picked (and its folders)" },
    .{ .sym = "op_file_new", .id = "file.new", .label = "New Scene", .doc = "Start again from the default scene", .code = 49, .mods = 4 },
    .{ .sym = "op_file_open", .id = "file.open", .label = "Open...", .doc = "Open a .bee scene: file.open <path>", .code = 24, .mods = 4 },
    .{ .sym = "op_file_save", .id = "file.save", .label = "Save", .doc = "Save the scene: file.save [path]", .code = 31, .mods = 4 },
    .{ .sym = "op_file_saveas", .id = "file.save_as", .label = "Save As...", .doc = "Save the scene under a new name", .code = 31, .mods = 5 },
    .{ .sym = "op_import_obj", .id = "file.import_obj", .label = "Import OBJ...", .doc = "Import a Wavefront OBJ: file.import_obj <path>" },
    .{ .sym = "op_import_stl", .id = "file.import_stl", .label = "Import STL...", .doc = "Import an STL (binary or ASCII): file.import_stl <path>" },
    .{ .sym = "op_export_obj", .id = "file.export_obj", .label = "Export OBJ...", .doc = "Export mesh objects as OBJ: file.export_obj <path>" },
    .{ .sym = "op_import_gltf", .id = "file.import_gltf", .label = "Import glTF...", .doc = "Import a glTF 2.0 scene (.gltf or .glb): file.import_gltf <path>" },
    .{ .sym = "op_export_gltf", .id = "file.export_gltf", .label = "Export glTF...", .doc = "Export mesh objects and materials as glTF 2.0 (.glb binary, .gltf text): file.export_gltf <path>" },
    .{ .sym = "op_export_stl", .id = "file.export_stl", .label = "Export STL...", .doc = "Export mesh objects as binary STL: file.export_stl <path>" },
    .{ .sym = "op_screenshot", .id = "view.screenshot", .label = "Screenshot", .doc = "Save the window as PNG: view.screenshot [path]", .code = 88, .mods = 1 },
    .{ .sym = "op_recover", .id = "file.recover", .label = "Recover Autosave", .doc = "Open the last autosave" },
    .{ .sym = "op_tree_new", .id = "tree.new", .label = "New Node Tree", .doc = "A new, empty geometry node tree: tree.new [name]" },
    .{ .sym = "op_tree_node", .id = "tree.node", .label = "Add Geometry Node", .doc = "Add a node to a tree: tree.node <tree> <type> [values]" },
    .{ .sym = "op_tree_link", .id = "tree.link", .label = "Link Geometry Nodes", .doc = "Feed a node's output into an input: tree.link <tree> <from[:output]> <to> <input 1-3> (the tree keeps itself in evaluation order)" },
    .{ .sym = "op_tree_set", .id = "tree.node_set", .label = "Set Geometry Node Value", .doc = "Set a node input (1-3) or value (4-7): tree.node_set <tree> <node> <slot> <x> [y z]" },
    .{ .sym = "op_tree_del", .id = "tree.node_delete", .label = "Delete Geometry Node", .doc = "Remove a node from a tree: tree.node_delete <tree> <node>" },
    .{ .sym = "op_tree_group", .id = "tree.group", .label = "Make Node Group", .doc = "Move nodes into a new tree run by one Group node: tree.group <tree> <node> [node ...]" },
    .{ .sym = "op_tree_move", .id = "tree.node_move", .label = "Move Geometry Node", .doc = "Place a node in the node editor: tree.node_move <tree> <node> <x> <y>" },
    .{ .sym = "op_mat_node", .id = "material.node", .label = "Add Shader Node", .doc = "Add a node to a material's graph: material.node <material> <type> [values] (image: <image> [size])" },
    .{ .sym = "op_mat_link", .id = "material.link", .label = "Link Shader Nodes", .doc = "Feed a node into another node's input: material.link <material> <from> <to> <input 1-3> [output 0-3] (any order; the graph is kept in evaluation order)" },
    .{ .sym = "op_mat_node_set", .id = "material.node_set", .label = "Set Shader Node Value", .doc = "Set a node input (1-3) or value (4-7): material.node_set <material> <node> <slot> <x> [y z]" },
    .{ .sym = "op_mat_socket", .id = "material.socket", .label = "Connect Material Socket", .doc = "Drive a Material Output pin by a node: material.socket <material> base|metallic|specular|roughness|emission|opacity|normal|ao|clearcoat|coat_roughness|transmission|ior|mask <node|none> [output 0-3]" },
    .{ .sym = "op_mat_node_delete", .id = "material.node_delete", .label = "Delete Shader Node", .doc = "Remove a node from a material's graph (its links go): material.node_delete <material> <node>" },
    .{ .sym = "op_mat_node_move", .id = "material.node_move", .label = "Move Shader Node", .doc = "Place a node in the node editor: material.node_move <material> <node (0: the output)> <x> <y>" },
    .{ .sym = "op_mat_nodes_clear", .id = "material.nodes_clear", .label = "Clear Shader Nodes", .doc = "Remove a material's graph: material.nodes_clear <material>" },
    .{ .sym = "op_add_ground", .id = "create.ground", .label = "Ground", .doc = "Add the Ground: an endless floor, drawn as a fading grid, that catches shadows in renders (over a transparent background) and that rigid bodies, cloth and the player land on: create.ground [height h]. A scene has one: with one there it is selected" },
    .{ .sym = "op_help_keys", .id = "help.shortcuts", .label = "Keyboard Shortcuts", .doc = "Every shortcut, searchable (F1; Esc closes)", .code = 59 },
    .{ .sym = "op_welcome", .id = "help.welcome", .label = "Welcome Screen", .doc = "Templates, recent files and samples to start from" },
    .{ .sym = "op_template", .id = "help.template", .label = "New from Template", .doc = "A new scene from a template: help.template empty|product|character|terrain|tree|ball" },
    .{ .sym = "op_hz_new", .id = "object.from_image", .label = "Model from Image (Hi3D)...", .doc = "A 3D model from a photo or drawing of one thing (the Hi3D addon, docs/HI3D.md): object.from_image <image> [512 | 1024 | 1536] (detail; 512 when not given). TripoSR makes the rough shape, Hi3D v1.0 the detail, on the GPU while you work; the model comes in at the 3D cursor" },
    .{ .sym = "op_hz_refine", .id = "object.refine_from_image", .label = "Refine from Image (Hi3D)...", .doc = "Carve a photo's detail into the active mesh (a rough block-out of the same thing, facing +Z) with the Hi3D addon: object.refine_from_image <image> [512 | 1024 | 1536]. The refined mesh takes its place; the original is hidden" },
    .{ .sym = "op_hz_stop", .id = "object.from_image_stop", .label = "Stop Image to 3D", .doc = "Stop the model being made from an image (object.from_image)" },
    .{ .sym = "op_hz_place", .id = "object.from_image_place", .label = "Model from Image", .doc = "(Image to 3D, when the helper is done) bring its mesh in: object.from_image_place <obj>", .hidden = true },
    .{ .sym = "op_render_image", .id = "render.image", .label = "Render Image", .doc = "Path-trace the scene (camera object, or the viewport) into a PNG: render.image <path> [width height samples [denoise]]" },
    .{ .sym = "op_image_load", .id = "image.load", .label = "Load Image...", .doc = "Load a PNG, JPEG or Radiance HDR image into the scene: image.load <path>" },
    .{ .sym = "op_image_new", .id = "image.new", .label = "New Image...", .doc = "A new image to paint on: image.new <name> [width height] (1024 x 1024 grey)" },
    .{ .sym = "op_image_save", .id = "image.save", .label = "Save Image...", .doc = "Save a scene image: image.save <name> <path.png|path.exr>" },
    .{ .sym = "op_la_import", .id = "landscape.import", .label = "Import Heightmap", .doc = "A landscape from a heightmap: landscape.import <file.png|file.exr> [size metres (1 a sample)] [height metres (PNG: 100; EXR: 1 x its values)] [base metres]. 16-bit PNGs (grey or colour: the first channel) and OpenEXR scanline files (Y, else R); 2^k + 1 samples a side, or resampled to it" },
    .{ .sym = "op_la_export", .id = "landscape.export", .label = "Export Heightmap", .doc = "The active landscape's heights to a file: landscape.export <file.png> (16-bit grey, lowest..highest) | <file.exr> (float metres); landscape.export <file.png> splat - its paint (RGBA: paint layers 1-4; 5-8 in <file>_2.png)" },
    .{ .sym = "op_la_tomesh", .id = "landscape.to_mesh", .label = "Landscape to Mesh", .doc = "Make the active landscape a plain mesh: landscape.to_mesh (the display grid) | landscape.to_mesh full (every sample, up to 2049 a side)" },
    .{ .sym = "op_la_tiles", .id = "landscape.tiles", .label = "Landscape Tiles", .doc = "Split the active landscape into k x k landscapes (its heights baked into each, its paint copied): landscape.tiles <k> - so world partition streams them by cell" },
    .{ .sym = "op_la_add", .id = "landscape.add", .label = "Landscape", .doc = "Add a landscape: a heightfield with a stack of layers (generate, erode, terrace, sculpted, flatten): landscape.add [flat|hills|mountains|canyon|dunes|island] [size metres (200)] [res samples a side (65-4097: 2^k + 1; 513)] [seed k]" },
    .{ .sym = "op_la_flat", .id = "landscape.add_flat", .label = "Flat", .doc = "Add a flat landscape (to sculpt): landscape.add flat" },
    .{ .sym = "op_la_hills", .id = "landscape.add_hills", .label = "Hills", .doc = "Add a landscape of eroded hills: landscape.add hills" },
    .{ .sym = "op_la_mount", .id = "landscape.add_mountains", .label = "Mountains", .doc = "Add a landscape of ridged, eroded mountains: landscape.add mountains" },
    .{ .sym = "op_la_canyon", .id = "landscape.add_canyon", .label = "Canyon", .doc = "Add a terraced canyon landscape: landscape.add canyon" },
    .{ .sym = "op_la_dunes", .id = "landscape.add_dunes", .label = "Dunes", .doc = "Add a landscape of dunes (billows, slid to their talus): landscape.add dunes" },
    .{ .sym = "op_la_island", .id = "landscape.add_island", .label = "Island", .doc = "Add an island landscape and its sea: a Water plane at the landscape's height (water material, ripples; bodies below it float): landscape.add island" },
    .{ .sym = "op_la_layer", .id = "landscape.layer", .label = "Landscape Layer", .doc = "Change the active landscape's layers: landscape.layer add <generate|erode|terrace|sculpted|flatten> [key value ...] | set <i> [key value ...] | remove <i> | hide <i> | show <i>. Keys: strength; generate: noise fbm|ridged|billow|cells, seed, scale, height, octaves; erode: droplets, rate, seed, thermal (iterations), talus (degrees); terrace: steps, smooth; flatten: height, at x z radius (adds a round area)" },
    .{ .sym = "op_la_set", .id = "landscape.set", .label = "Landscape Settings", .doc = "The active landscape's size and samples: landscape.set [size metres] [res samples a side] [detail display samples a side (at most)]" },
    .{ .sym = "op_la_water", .id = "landscape.add_water", .label = "Water", .doc = "Add a Water plane at the 3D cursor: bodies below its level float (the water material, ripples): landscape.add_water [size metres (200)]" },
    .{ .sym = "op_la_sea", .id = "landscape.sea", .label = "Add Sea", .doc = "Add a sea to the active landscape: a Water plane 1.5 times its size at its height" },
    .{ .sym = "op_light_set", .id = "light.set", .label = "Light Settings", .doc = "The active light's settings: light.set power <p> | color <r> <g> <b> | type point|sun|spot|area | size <radius m, sun angle deg, area edge m> | angle <spot cone deg> (power 1: the default light)" },
    .{ .sym = "op_camera_set", .id = "camera.set", .label = "Camera Settings", .doc = "The active camera's lens, or make it the one that renders: camera.set lens <mm> | active" },
    .{ .sym = "op_lb_save", .id = "lib.save", .label = "Save to Library", .doc = "Save to the content library: lib.save object|rig|scene [name] [#tag ...] (the selected objects, an armature with its skinned meshes, the scene) or lib.save material|tree|action <name> [#tag ...]" },
    .{ .sym = "op_lb_place", .id = "lib.place", .label = "Place Asset", .doc = "Put a library asset into the scene: lib.place <name or id> [x y z] (default: the 3D cursor; a scene opens instead)" },
    .{ .sym = "op_lb_tag", .id = "lib.tag", .label = "Tag Asset", .doc = "Tag an asset: lib.tag <asset> <tag> [-tag ...] (-tag takes one away)" },
    .{ .sym = "op_lb_remove", .id = "lib.remove", .label = "Remove Asset", .doc = "Take an asset out of its library (its blob goes when nothing else uses it): lib.remove <asset>" },
    .{ .sym = "op_lb_search", .id = "lib.search", .label = "Search Library", .doc = "Show the assets whose name, kind or tags hold every word: lib.search [words]" },
    .{ .sym = "op_lb_deps", .id = "lib.deps", .label = "Asset Dependencies", .doc = "What an asset uses and what uses it: lib.deps <asset>" },
    .{ .sym = "op_lb_pack", .id = "lib.pack", .label = "Pack Assets", .doc = "Write an asset pack (a .bee file: a manifest, each blob once, thumbnails): lib.pack <path> [search words]" },
    .{ .sym = "op_lb_import", .id = "lib.import", .label = "Import Asset Pack", .doc = "Merge an asset pack into the library: lib.import <path>" },
    .{ .sym = "op_lb_add", .id = "lib.add", .label = "Add Library", .doc = "List another library folder's assets too: lib.add <folder>" },
    .{ .sym = "op_lb_list", .id = "lib.list", .label = "List Library", .doc = "List the library's assets (kind, name, tags)" },
    .{ .sym = "op_lb_thumbs", .id = "lib.thumbnails", .label = "Make Thumbnails", .doc = "Path-trace every missing thumbnail now (the window makes them in the background)" },
    .{ .sym = "op_lb_thumb", .id = "lib.thumbnail", .label = "Make a Thumbnail", .doc = "(a child process) path-trace one asset's thumbnail: lib.thumbnail <id>", .hidden = true },
    .{ .sym = "op_lm_bake", .id = "lightmap.bake", .label = "Bake Lightmap", .doc = "Bake the light on every visible mesh into one lightmap atlas with the path tracer (a second UV set per object, packed; denoised, dilated): lightmap.bake [size 64-4096, default 512] [rays a texel, default 64]" },
    .{ .sym = "op_lm_save", .id = "lightmap.save", .label = "Save Lightmap", .doc = "Write the lightmap atlas: lightmap.save <file.exr | file.png> (EXR linear half floats, PNG sRGB clamped)" },
    .{ .sym = "op_lm_clear", .id = "lightmap.clear", .label = "Clear Lightmap", .doc = "Forget the baked lightmap" },
    .{ .sym = "op_link_serve", .id = "link.serve", .label = "Serve Live Link", .doc = "Stream the scene to peers (other BeeModels, game engines): link.serve [port] (localhost, default 7461) | lan [port] (every interface) | unix:<path>" },
    .{ .sym = "op_link_stop", .id = "link.stop", .label = "Stop Live Link", .doc = "Stop serving the live link (peers are let go)" },
    .{ .sym = "op_link_connect", .id = "link.connect", .label = "Mirror a Session", .doc = "Mirror another BeeModel's scene over its live link: link.connect host:port | unix:<path> (IPv4 numbers or localhost)" },
    .{ .sym = "op_link_disconnect", .id = "link.disconnect", .label = "Stop Mirroring", .doc = "Stop mirroring (the scene stays as it is)" },
    .{ .sym = "op_lv_dn", .id = "view.rendered_denoise", .label = "Denoise Rendered", .doc = "Rendered shading: denoise the path-traced samples on the GPU every frame: view.rendered_denoise [0|1] (none: on or off; kept in the preferences)" },
    .{ .sym = "op_lv_play", .id = "view.rendered_playback", .label = "Rendered Playback Samples", .doc = "Rendered shading while the animation plays: path-traced samples each new frame gets, denoised: view.rendered_playback <0..64> (0: the raycast; kept in the preferences)" },
    .{ .sym = "op_lv_move", .id = "view.rendered_motion", .label = "Rendered Motion Samples", .doc = "Rendered shading while the view or the scene changes: path-traced samples each frame gets, denoised, instead of the raycast: view.rendered_motion <0..4> (0: the raycast; kept in the preferences)" },
    .{ .sym = "op_lv_spp", .id = "view.rendered_samples", .label = "Rendered Samples", .doc = "Rendered shading's path-traced samples once the view is still: view.rendered_samples <0..4096> (0: the raycast alone; kept in the preferences)" },
    .{ .sym = "op_logic_new", .id = "logic.new", .label = "New Logic Graph", .doc = "A new, empty logic graph (a node tree that runs in play mode): logic.new [name]" },
    .{ .sym = "op_logic_attach", .id = "logic.attach", .label = "Attach Logic", .doc = "Run a logic graph on an object in play mode (a Logic modifier): logic.attach <graph> [object]" },
    .{ .sym = "op_logic_node", .id = "logic.node", .label = "Add Logic Node", .doc = "Add a node to a logic graph: logic.node <graph> <type> [values] (types: begin tick key overlap hit timer message move rotate set_property spawn destroy play_action impulse visibility send set_variable branch variable math info get_property shatter set_strength field); link and set with tree.link / tree.node_set" },
    .{ .sym = "op_logic_name", .id = "logic.name", .label = "Set Logic Name", .doc = "Set a node's name value (a message, an object, a property, an action): logic.name <graph> <node> <value 4-7> [text]" },
    .{ .sym = "op_lt_raise", .id = "landscape.tool_raise", .label = "Raise", .doc = "Landscape sculpting: raise the ground under the brush" },
    .{ .sym = "op_lt_lower", .id = "landscape.tool_lower", .label = "Lower", .doc = "Landscape sculpting: lower the ground under the brush" },
    .{ .sym = "op_lt_smooth", .id = "landscape.tool_smooth", .label = "Smooth", .doc = "Landscape sculpting: smooth the ground towards its neighbours" },
    .{ .sym = "op_lt_flatten", .id = "landscape.tool_flatten", .label = "Flatten", .doc = "Landscape sculpting: flatten to the height where the stroke began" },
    .{ .sym = "op_lt_ramp", .id = "landscape.tool_ramp", .label = "Ramp", .doc = "Landscape sculpting: a straight slope from where the stroke begins to where it ends" },
    .{ .sym = "op_lt_noise", .id = "landscape.tool_noise", .label = "Noise", .doc = "Landscape sculpting: roughen the ground with noise" },
    .{ .sym = "op_lt_erode", .id = "landscape.tool_erode", .label = "Erode", .doc = "Landscape sculpting: droplet erosion under the brush" },
    .{ .sym = "op_lt_rock", .id = "landscape.paint_rock", .label = "Rock", .doc = "Landscape painting: paint rock (a paint layer is added when there is none)" },
    .{ .sym = "op_lt_grass", .id = "landscape.paint_grass", .label = "Grass", .doc = "Landscape painting: paint grass" },
    .{ .sym = "op_lt_sand", .id = "landscape.paint_sand", .label = "Sand", .doc = "Landscape painting: paint sand" },
    .{ .sym = "op_lt_snow", .id = "landscape.paint_snow", .label = "Snow", .doc = "Landscape painting: paint snow" },
    .{ .sym = "op_lt_dirt", .id = "landscape.paint_dirt", .label = "Dirt", .doc = "Landscape painting: paint dirt" },
    .{ .sym = "op_lt_gravel", .id = "landscape.paint_gravel", .label = "Gravel", .doc = "Landscape painting: paint gravel" },
    .{ .sym = "op_lt_moss", .id = "landscape.paint_moss", .label = "Moss", .doc = "Landscape painting: paint moss" },
    .{ .sym = "op_lt_mud", .id = "landscape.paint_mud", .label = "Mud", .doc = "Landscape painting: paint mud" },
    .{ .sym = "op_lt_auto", .id = "landscape.paint_auto", .label = "Auto Paint", .doc = "Paint the active landscape by its paint layers' rules (height and slope; rock on slopes, grass on the flat, ...)" },
    .{ .sym = "op_ls_brush", .id = "landscape.brush", .label = "Landscape Brush", .doc = "One dab on the active landscape: landscape.brush <raise|lower|smooth|flatten|noise|erode|rock|grass|sand|snow|dirt|gravel|moss|mud> x z [radius r (10)] [strength s (0.5)]; landscape.brush ramp x z to x2 z2 [radius r] (world x, z)" },
    .{ .sym = "op_ls_paint", .id = "landscape.paint", .label = "Landscape Paint Layers", .doc = "The active landscape's paint layers: landscape.paint add <rock|grass|sand|snow|dirt|gravel|moss|mud> [colour r g b] [friction f] [bounce b] | rule <i> [height lo hi (0..1)] [slope lo hi (degrees)] | remove <i> | auto" },
    .{ .sym = "op_mat_new", .id = "material.new", .label = "New Material", .doc = "Create a material and give it to the active mesh: material.new [name]" },
    .{ .sym = "op_mat_assign", .id = "material.assign", .label = "Assign Material", .doc = "Give the active mesh a material: material.assign <name> (none = no material)" },
    .{ .sym = "op_mat_set", .id = "material.set", .label = "Set Material Value", .doc = "Set a material value: material.set <name> base|metallic|roughness|specular|ior|transmission|emission|strength|clearcoat|coat_roughness|alpha|density|blend|one_sided|clip <values> (blend 0 opaque, 1 masked, 2 translucent)" },
    .{ .sym = "op_mat_texture", .id = "material.texture", .label = "Material Texture", .doc = "Give a material a base colour image, box-projected (a one-node graph): material.texture <name> <image|none> [size]" },
    .{ .sym = "op_mat_remove", .id = "material.remove", .label = "Remove Material", .doc = "Delete a material (objects using it get none): material.remove <name>" },
    .{ .sym = "op_mat_fn_new", .id = "material.function_new", .label = "New Material Function", .doc = "A new material function (a graph used by Material Function nodes, In 1..3 to Out 1..3): material.function_new [name]" },
    .{ .sym = "op_mat_make_fn", .id = "material.make_function", .label = "Make Material Function", .doc = "Move nodes into a new material function, one Material Function node in their place (node editor: Ctrl+G): material.make_function <material> <node> [node...]" },
    .{ .sym = "op_mat_instance", .id = "material.instance", .label = "New Material Instance", .doc = "A material instance: the parent's graph and values, its parameters overridable: material.instance <parent> [name] (the active mesh gets it)" },
    .{ .sym = "op_mat_param", .id = "material.param", .label = "Set Material Parameter", .doc = "Set a parameter node's value by name (an instance: overrides it): material.param <material> <parameter> <x> [y z w]" },
    .{ .sym = "op_mat_param_reset", .id = "material.param_reset", .label = "Reset Material Parameter", .doc = "An instance's parameter back to the parent's value: material.param_reset <material> <parameter>" },
    .{ .sym = "op_mat_node_name", .id = "material.node_name", .label = "Name Parameter", .doc = "Name a parameter node: material.node_name <material> <node> <name>" },
    .{ .sym = "op_mat_import_tex", .id = "material.import_textures", .label = "Import Texture Set...", .doc = "A PBR material from a texture set: pick any one of its images (base colour, normal, roughness, metallic, AO, height, emission, opacity, ORM are found by name): material.import_textures <image> [name]" },
    .{ .sym = "op_mat_bake", .id = "material.bake", .label = "Bake Material", .doc = "Bake an object's material (its node graph) through its UVs into images <material>_base, _orm (occlusion, roughness, metallic), _normal and _emissive; apply: the material then samples them: material.bake <object> [size] [apply]" },
    .{ .sym = "op_mat_apply", .id = "material.apply_preset", .label = "Apply Material Preset", .doc = "Give the selected mesh objects a preset look (the wheel's Material choices): the material named like the preset, made the first time and set to the preset again after: material.apply_preset <preset>" },
    .{ .sym = "op_mat_preset", .id = "material.preset", .label = "Material Preset", .doc = "Give a material a preset look (none named: a new one for the active mesh): material.preset <gold|silver|copper|chrome|aluminium|plastic|rubber|glass|frosted_glass|water|ceramic|car_paint|wood|marble|concrete|fabric|leather|skin|clay|emissive> [material]" },
    .{ .sym = "op_mat_instance_ui", .id = "material.new_instance", .label = "New Instance", .doc = "A material instance of this one: the same graph, its parameters yours to override", .hidden = true },
    .{ .sym = "op_mat_bake_ui", .id = "material.bake_active", .label = "Bake to Maps", .doc = "Bake this material's node graph through the object's UVs into base colour, ORM, normal and emissive maps (1024 x 1024) that the material then samples", .hidden = true },
    .{ .sym = "op_obj_measure", .id = "object.measure", .label = "Mass Properties", .doc = "Volume, surface area, mass (from the material's density) and centre of mass of the selected meshes, in scene units" },
    .{ .sym = "op_view_measure", .id = "view.measure", .label = "Measure", .doc = "Measure in the viewport: click two points for a distance, a third for the angle at the middle one; Esc ends", .code = 50, .mods = 1 },
    .{ .sym = "op_mj_add", .id = "mech.joint", .label = "Add Mechanism Joint", .doc = "Join a part to its parent so it moves: mech.joint <revolute|slider> <part> <parent|world> [pivot x y z] [axis x y z] [min e] [max e] [gear <joint> <ratio>] [value <expression>] (the part as it is now is its place at 0; values: parameters, units, frame)" },
    .{ .sym = "op_mj_set", .id = "mech.set", .label = "Set Mechanism Joint", .doc = "Change a joint (1..): mech.set <n> value <expression> | min <e> | max <e> | nolimits | gear <joint> <ratio>" },
    .{ .sym = "op_mj_rem", .id = "mech.remove", .label = "Remove Mechanism Joint", .doc = "Remove a mechanism joint: mech.remove <n>" },
    .{ .sym = "op_mj_list", .id = "mech.list", .label = "List Mechanism Joints", .doc = "The mechanism's joints and their values, in the console" },
    .{ .sym = "op_mj_check", .id = "mech.check", .label = "Check Collisions", .doc = "Which of the mechanism's parts collide now" },
    .{ .sym = "op_asm_mate", .id = "asm.mate", .label = "Mate Parts", .doc = "Place a part against another: asm.mate <coincident|concentric|distance> <part> <face|axis px py pz dx dy dz> <target> <face|axis ...> [distance] [flip] (faces: centre and normal; axis: in the object's own space; the part moves, once)" },
    .{ .sym = "op_m_extrude", .id = "mesh.extrude", .label = "Extrude", .doc = "Extrude the selected faces (or edges) and move them along the normal: mesh.extrude [distance]", .code = 18 },
    .{ .sym = "op_m_extrude_ind", .id = "mesh.extrude_individual", .label = "Extrude Individual Faces", .doc = "Extrude every selected face along its own normal: mesh.extrude_individual [distance]", .code = 18, .mods = 8 },
    .{ .sym = "op_m_inset", .id = "mesh.inset", .label = "Inset Faces", .doc = "Inset every selected face: mesh.inset [thickness]", .code = 23 },
    .{ .sym = "op_m_subdivide", .id = "mesh.subdivide", .label = "Subdivide", .doc = "Split the selected faces (quads into four)" },
    .{ .sym = "op_m_fill", .id = "mesh.fill", .label = "Fill / Make Face", .doc = "Make a face from the selected vertices (fills holes)", .code = 33 },
    .{ .sym = "op_m_dissolve", .id = "mesh.dissolve", .label = "Dissolve", .doc = "Dissolve the selection by select mode: merge the faces around it into n-gons", .code = 45, .mods = 4 },
    .{ .sym = "op_m_merge_c", .id = "mesh.merge_center", .label = "Merge at Center", .doc = "Merge all selected vertices into one at their centre", .code = 50 },
    .{ .sym = "op_m_merge_col", .id = "mesh.merge_collapse", .label = "Merge Collapse", .doc = "Merge each connected group of selected vertices at its centre" },
    .{ .sym = "op_m_merge_d", .id = "mesh.merge_distance", .label = "Merge by Distance", .doc = "Merge selected vertices closer than a distance: mesh.merge_distance [0.0001]" },
    .{ .sym = "op_m_del", .id = "mesh.delete", .label = "Delete", .doc = "Delete by select mode: vertices, edges or faces", .code = 45, .hidden = true },
    .{ .sym = "op_m_del_key", .id = "mesh.delete_key", .label = "Delete", .doc = "Delete by select mode (Delete key)", .code = 111, .hidden = true },
    .{ .sym = "op_m_del_v", .id = "mesh.delete_vertices", .label = "Delete Vertices", .doc = "Delete the selected vertices and their faces" },
    .{ .sym = "op_m_del_e", .id = "mesh.delete_edges", .label = "Delete Edges", .doc = "Delete the faces around the selected edges" },
    .{ .sym = "op_m_del_f", .id = "mesh.delete_faces", .label = "Delete Faces", .doc = "Delete the selected faces" },
    .{ .sym = "op_m_dup", .id = "mesh.duplicate", .label = "Duplicate", .doc = "Duplicate the selected faces and move the copy", .code = 32, .mods = 1 },
    .{ .sym = "op_m_flip", .id = "mesh.flip_normals", .label = "Flip Normals", .doc = "Reverse the selected faces" },
    .{ .sym = "op_m_recalc", .id = "mesh.recalc_normals", .label = "Recalculate Normals", .doc = "Make the faces consistent and point them outside (selected, or all)", .code = 49, .mods = 1 },
    .{ .sym = "op_m_loopcut", .id = "mesh.loopcut", .label = "Loop Cut", .doc = "Cut a ring of quads: Ctrl+R then click; scripts: mesh.loopcut \"a b [cuts]\"", .code = 19, .mods = 4 },
    .{ .sym = "op_m_knife", .id = "mesh.knife", .label = "Knife", .doc = "Draw a cut across the visible faces: click points, Enter cuts", .code = 37 },
    .{ .sym = "op_m_bisect", .id = "mesh.bisect", .label = "Bisect", .doc = "Cut the mesh with a plane: mesh.bisect \"px py pz nx ny nz\" (world; default: horizontal through the 3D cursor)" },
    .{ .sym = "op_m_bevel", .id = "mesh.bevel", .label = "Bevel", .doc = "Bevel the selected edges: drag the width, wheel = segments; scripts: mesh.bevel \"width [segments]\"", .code = 48, .mods = 4 },
    .{ .sym = "op_m_bridge", .id = "mesh.bridge", .label = "Bridge Edge Loops", .doc = "Join two selected boundary loops with a band of quads" },
    .{ .sym = "op_m_spin", .id = "mesh.spin", .label = "Spin", .doc = "Sweep the selected edges around the 3D cursor: mesh.spin \"[steps] [degrees] [x|y|z]\" (12 360 y)" },
    .{ .sym = "op_cursor_reset", .id = "view.cursor_reset", .label = "Reset 3D Cursor", .doc = "Put the 3D cursor back at the origin (Shift+right click places it)" },
    .{ .sym = "op_mod_add", .id = "object.modifier_add", .label = "Add Modifier", .doc = "Add a modifier to the active mesh: object.modifier_add mirror|array|solidify|subsurf|bevel|decimate|remesh|boolean|multires" },
    .{ .sym = "op_mod_mirror", .id = "object.modifier_add_mirror", .label = "Mirror", .doc = "Add a Mirror modifier", .hidden = true },
    .{ .sym = "op_mod_array", .id = "object.modifier_add_array", .label = "Array", .doc = "Add an Array modifier", .hidden = true },
    .{ .sym = "op_mod_solidify", .id = "object.modifier_add_solidify", .label = "Solidify", .doc = "Add a Solidify modifier", .hidden = true },
    .{ .sym = "op_mod_subsurf", .id = "object.modifier_add_subsurf", .label = "Subdivision Surface", .doc = "Add a Subdivision Surface modifier (Ctrl+2)", .code = 3, .mods = 4, .hidden = true },
    .{ .sym = "op_mod_bevel", .id = "object.modifier_add_bevel", .label = "Bevel", .doc = "Add a Bevel modifier", .hidden = true },
    .{ .sym = "op_mod_decimate", .id = "object.modifier_add_decimate", .label = "Decimate", .doc = "Add a Decimate modifier", .hidden = true },
    .{ .sym = "op_mod_remesh", .id = "object.modifier_add_remesh", .label = "Remesh", .doc = "Add a Remesh modifier", .hidden = true },
    .{ .sym = "op_mod_boolean", .id = "object.modifier_add_boolean", .label = "Boolean", .doc = "Add a Boolean modifier (the other selected mesh is its object)", .hidden = true },
    .{ .sym = "op_mod_multires", .id = "object.modifier_add_multires", .label = "Multiresolution", .doc = "Add a Multires modifier: subdivision levels that keep sculpted detail (sculpt at any level)", .hidden = true },
