    .{ .sym = "op_par_set", .id = "object.parent_set", .label = "Parent", .doc = "The selected objects become children of the active one (they keep where they are, then follow it): object.parent_set [child parent]", .code = 25, .mods = 4 },
    .{ .sym = "op_par_clear", .id = "object.parent_clear", .label = "Clear Parent", .doc = "The selected objects no longer follow a parent (they stay where they are)", .code = 25, .mods = 8 },
    .{ .sym = "op_ps_add", .id = "particles.add", .label = "Particle System", .doc = "Add a particle system to the active object: particles.add [rain|snow|sparks|confetti|fountain|tank (a preset, then:)] [from faces|volume|verts|point] [rate n | burst n] [start f] [end f] [life s] [life_random 0..1] [speed m/s] [speed_random 0..1] [normal | direction x y z] [spread deg] [size m] [size_random 0..1] [drag k] [gravity k] [color RRGGBB] [seed n] [group 0..15] [max n] [name text] [on|off]" },
    .{ .sym = "op_ps_set", .id = "particles.set", .label = "Particle Settings", .doc = "A particle system's settings on the active object: particles.set [system n] then the words particles.add takes" },
    .{ .sym = "op_ps_export", .id = "file.export_liquid", .label = "Export Liquid Surface...", .doc = "Export the active object's liquid surface (or its mesh) at each frame as OBJ files: file.export_liquid <prefix> [first last] (prefix_0001.obj ..., the scene's frames when not said)" },
    .{ .sym = "op_ps_remove", .id = "particles.remove", .label = "Remove Particle System", .doc = "Remove a particle system from the active object: particles.remove [system n] (the first when not said)" },
    .{ .sym = "op_ps_rain", .id = "particles.add_rain", .label = "Rain", .doc = "Add rain: a cloud (a 10 m plane 8 m up) raining drops that die where they land" },
    .{ .sym = "op_ps_snow", .id = "particles.add_snow", .label = "Snow", .doc = "Add snow: a cloud of slowly falling flakes that stick where they land" },
    .{ .sym = "op_ps_sparks", .id = "particles.add_sparks", .label = "Sparks", .doc = "Add sparks: hot, short-lived, bouncing, yellow to red" },
    .{ .sym = "op_ps_confetti", .id = "particles.add_confetti", .label = "Confetti", .doc = "Add confetti: a burst of 600 drifting down" },
    .{ .sym = "op_ps_fountain", .id = "particles.add_fountain", .label = "Fountain", .doc = "Add a fountain: a jet of water drops" },
    .{ .sym = "op_ps_tank", .id = "particles.add_tank", .label = "Water Tank", .doc = "Add a water tank: a block of liquid in a box twice its size, meshed into a surface" },
    .{ .sym = "op_pu_bake", .id = "particles.bake", .label = "Bake Particles", .doc = "Bake the particles and liquids (sim.bake particles liquid)" },
    .{ .sym = "op_pu_free", .id = "particles.free", .label = "Free Particles Cache", .doc = "Free the particles' and liquids' cache and bake (sim.free particles liquid)" },
    .{ .sym = "op_play_start", .id = "play.start", .label = "Play", .doc = "Play the scene: walk (or fly) from the viewport's eye while simulations and animations run; Esc stops (keep or discard the changes): play.start [walk|fly] [x y z]", .code = 63 },
    .{ .sym = "op_play_stop", .id = "play.stop", .label = "Stop Playing", .doc = "Stop play mode: play.stop [keep|discard] (default: discard - the scene as it was)" },
    .{ .sym = "op_play_mode", .id = "play.mode", .label = "Walk / Fly", .doc = "Switch play mode between walking and flying: play.mode walk|fly" },
    .{ .sym = "op_edit_prefs", .id = "edit.preferences", .label = "Preferences...", .doc = "Open the Preferences (Ctrl+Comma): interface, input, keymap, system, files and the AI connections", .code = 51, .mods = 4 },
    .{ .sym = "op_ui_scale", .id = "view.ui_scale", .label = "UI Scale", .doc = "Make everything bigger or smaller, on top of the screen's own scale: view.ui_scale <75..200> (percent; kept in the preferences)" },
    .{ .sym = "op_prefs_keymap", .id = "prefs.keymap", .label = "Keymap Preset", .doc = "The keymap: prefs.keymap beemodel | blender (Blender 4.x's keys where BeeModel's differ, your own keys kept)" },
    .{ .sym = "op_accent_none", .id = "view.accent_theme", .label = "Theme's Accent", .doc = "The UI accent colour back to the theme's own" },
    .{ .sym = "op_print_check", .id = "mesh.print_check", .label = "Print Check", .doc = "For 3D printing, per selected mesh: closed or not, the thinnest wall and faces under the minimum, overhang area, size (Z up, mm): mesh.print_check [minimum wall mm, default 1]" },
    .{ .sym = "op_show_thin", .id = "view.show_thickness", .label = "Show Thin Walls", .doc = "Colour the active mesh's faces by wall thickness: red under the minimum, yellow under twice it: view.show_thickness [minimum mm, default 1]" },
    .{ .sym = "op_pk_show", .id = "mesh.print_show", .label = "Show Print Check Finding", .doc = "Select a Print Check finding in edit mode and frame it: mesh.print_show edges|thin|overhangs", .hidden = true },
    .{ .sym = "op_probe_add", .id = "probe.add", .label = "Add Light Probe", .doc = "Add a light probe: probe.add irradiance|reflection [x y z] [half size x y z] [grid points x y z] (an irradiance volume: grid points over its box; a reflection probe: a cube map from its centre, box-projected); probe.bake bakes them" },
    .{ .sym = "op_probe_bake", .id = "probe.bake", .label = "Bake Light Probes", .doc = "Bake every light probe with the path tracer: probe.bake [rays a point] (default 256; reflection probes: an eighth of that a texel, at least 4)" },
    .{ .sym = "op_probe_remove", .id = "probe.remove", .label = "Remove Light Probe", .doc = "Remove a light probe: probe.remove <number from 1>" },
    .{ .sym = "op_probe_clear", .id = "probe.clear", .label = "Remove All Light Probes", .doc = "Remove every light probe" },
    .{ .sym = "op_rb_add", .id = "rigid.add", .label = "Add Rigid Body", .doc = "Make the selected objects rigid bodies (or change them): rigid.add [active|passive] [box|sphere|capsule|hull|compound] [instances|object] [mass m] [friction f] [bounce b] [damping d] [velocity x y z] [group n] [collide bits] [attracts|noattract] (attracts: it pulls the other bodies by its mass). Active ones fall when the frame goes past the start; instances: each instance of the object's geometry (nodes) is a body of its own, shaped like its prototype" },
    .{ .sym = "op_rb_rem", .id = "rigid.remove", .label = "Remove Rigid Body", .doc = "The selected objects are no longer rigid bodies" },
    .{ .sym = "op_rb_joint", .id = "rigid.joint", .label = "Add Joint", .doc = "Tie two bodies (or one to the world): rigid.joint <fixed|hinge|point|slider> <object> <object|world> [pivot x y z] [axis x y z] [break force] [limits lo hi] [motor speed force] (pivot: the first object's place; axis: Y; hinge limits and motor speed in degrees)" },
    .{ .sym = "op_rb_world", .id = "rigid.world", .label = "Physics World", .doc = "Physics settings: rigid.world [gravity x y z] [g n (bodies that attract: G, 1 by default)] [rate steps-a-second] [iterations n (a step, over its substeps)] [substeps n (1-64; 4)]" },
    .{ .sym = "op_redo_last", .id = "edit.redo_last", .label = "Adjust Last Operation", .doc = "Run the last operation again with new values: edit.redo_last \"values\" (as the redo panel shows them)" },
    .{ .sym = "op_redo_prompt", .id = "edit.redo_prompt", .label = "Adjust Last Operation...", .doc = "F9: type new values for the last operation", .code = 67 },
    .{ .sym = "op_ref_add", .id = "object.add_reference", .label = "Reference Image...", .doc = "A reference image to model over: object.add_reference <image file> (PNG, JPEG, HDR) - a flat object at the 3D cursor, square to the view, not rendered" },
    .{ .sym = "op_refs_add", .id = "object.add_references", .label = "Reference Images from Folder...", .doc = "A building's drawings as reference images: object.add_references <folder | file.pdf | image>. PDF pages (poppler) and images, sorted by name and title block into elevations, plans, sections, site; at their true scale (1:50 in the text), set up around the building in a folder of their own" },
    .{ .sym = "op_ref_pin", .id = "object.reference_pin", .label = "Pin Reference Pixel", .doc = "Move a reference image so its image's pixel u,v (0,0 its top-left) lies at the point x,y,z: object.reference_pin <reference> <u> <v> <x> <y> <z>. Lines drawings up: the same corner pinned in each", .hidden = true },
    .{ .sym = "op_ref_kind", .id = "object.reference_kind", .label = "Reference Kind", .doc = "Set what a reference drawing is and stand it so: object.reference_kind <reference> front|back|left|right|plan|section|site|terrain|other [level [turn]] (a plan's storey, 3 m each; turn: degrees about Y). It moves to its kind's folder", .hidden = true },
    .{ .sym = "op_refs_ai", .id = "object.references_ai", .label = "Line Up References with AI", .doc = "Ask the AI Assistant to check the reference drawings (of the selected reference's folder, or the last import) and line them up: it looks at each page, fixes the ones taken wrongly and pins them to the same corner" },
    .{ .sym = "op_render_start", .id = "render.start", .label = "Render", .doc = "Start a progressive render in the Render area (the scene at the render settings)", .code = 88 },
    .{ .sym = "op_render_stop", .id = "render.stop", .label = "Stop Render", .doc = "Stop the running render (keeps the samples so far)" },
    .{ .sym = "op_render_save", .id = "render.save", .label = "Save Render...", .doc = "Save the render as PNG, or .exr (linear half floats): render.save <path> [beauty|albedo|normal|depth]" },
    .{ .sym = "op_render_pass", .id = "render.pass", .label = "Next Render Pass", .doc = "Show a render pass: render.pass [beauty|albedo|normal|depth] (none: the next)" },
    .{ .sym = "op_render_device", .id = "render.device", .label = "Render Device", .doc = "Where renders run: render.device [auto|rtx|gpu|cpu] (auto: the best there is - RTX ray tracing, the GPU, else the CPU; none: says which; kept in the preferences)" },
    .{ .sym = "op_render_anim", .id = "render.animation", .label = "Render Animation...", .doc = "Render every frame at the render settings into a video or a folder: render.animation <file or folder> [first last] (none: the animation's range). .mp4 .mov .mkv .webm .gif go through ffmpeg; .apng is an animated PNG; .png or a folder: 0001.png ... Esc stops it, keeping the frames done" },
    .{ .sym = "op_render_reuse", .id = "render.sample_reuse", .label = "Sample Reuse", .doc = "Animation renders (render.animation, render_frames) reuse samples from up to so many frames before where a pixel sees the same surface, tracing only samples / (frames + 1) new ones: render.sample_reuse <frames> (0: off, up to 16)" },
